import React from 'react';

export default function StatCard({ title, value, change, note, icon, tone }) {
  return <section className="stat-card"><div className="stat-top"><span>{title}</span><i className={`stat-icon ${tone}`}>{icon}</i></div><div className="stat-number">{value}</div><div className="stat-note"><b className={tone}>{change}</b><span>{note}</span></div></section>;
}
